function stylePackHas(pack, tool2) {
  const i = tool2.indexOf(":");
  const kind = tool2.slice(0, i);
  const id = tool2.slice(i + 1);
  switch (kind) {
    case "tile":
      return pack.tiles.includes(id);
    case "prop":
      return pack.props.includes(id);
    case "scenario":
      return MODE_PIECES.has(id) || pack.gameplay.includes(id);
    case "mount":
      return pack.mounts.includes(id);
    case "pickup":
      return pack.pickups.includes(id);
    default:
      return true;
  }
}
